CREATE OR REPLACE FUNCTION public.dl_cash_lock()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int; s numeric;
begin
  if current_setting('dl.cash_sync', true) = '1' then return new; end if;
  if new.rt_id is null or new.expenses is not distinct from old.expenses then return new; end if;
  select count(*), coalesce(sum(net + coalesce(vat, 0)), 0) into n, s
    from ct_cost_lines where rt_id = new.rt_id and pay_source = 'CASH';
  if n > 0 then
    raise exception 'dl_cash_lock: Μετρητά Μ = γραμμές CASH του δρομολογίου (% γραμμές, % €) — καταχώρησε ή διόρθωσε τη γραμμή στα Έξοδα Δρομολογίων', n, s
      using errcode = 'check_violation';
  end if;
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.dl_cash_sync(p_rt bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare e dl_entries%rowtype; n int; s numeric;
begin
  if p_rt is null then return; end if;
  select count(*), coalesce(sum(net + coalesce(vat, 0)), 0) into n, s
    from ct_cost_lines where rt_id = p_rt and pay_source = 'CASH';
  select * into e from dl_entries where rt_id = p_rt and deleted_at is null and entry_type = 'trip' limit 1;
  if e.id is null then return; end if;

  perform set_config('dl.cash_sync', '1', true);
  if n > 0 then
    if e.expenses is distinct from s then
      update dl_entries
         set expenses = s, expenses_auto = true, updated_at = now(),
             needs_review = case when e.expenses is not null and not e.expenses_auto then true else needs_review end,
             review_note  = case when e.expenses is not null and not e.expenses_auto
                              then concat_ws(' · ', review_note,
                                   'Μετρητά Μ ' || e.expenses || ' € χειροκίνητο ≠ γραμμές CASH ' || s || ' € (' || n || ') — ξαναγράφτηκε από τις γραμμές ' || to_char(now(), 'DD/MM/YYYY') || ' (042)')
                              else review_note end
       where id = e.id;
      perform rt_sync_audit('update', 'dl_entries', e.id::text,
        jsonb_build_object('expenses', e.expenses, 'expenses_auto', e.expenses_auto),
        jsonb_build_object('expenses', s, 'expenses_auto', true, 'cash_lines', n, 'rt_id', p_rt,
                           'reason', 'Μετρητά Μ = Σ CASH lines of the round trip (042)'));
    elsif not e.expenses_auto then
      update dl_entries set expenses_auto = true where id = e.id;
    end if;
  elsif e.expenses_auto then
    update dl_entries set expenses = null, expenses_auto = false, updated_at = now() where id = e.id;
    perform rt_sync_audit('update', 'dl_entries', e.id::text,
      jsonb_build_object('expenses', e.expenses, 'expenses_auto', true),
      jsonb_build_object('expenses', null, 'expenses_auto', false, 'rt_id', p_rt,
                         'reason', 'last CASH line of the round trip removed — auto Μετρητά Μ cleared (042)'));
  end if;
  perform set_config('dl.cash_sync', '0', true);
end $function$
;
CREATE OR REPLACE FUNCTION public.dl_cash_sync_entry()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.rt_id is not null and new.deleted_at is null and new.entry_type = 'trip' then perform dl_cash_sync(new.rt_id); end if;
  return null;
end $function$
;
CREATE OR REPLACE FUNCTION public.dl_local_day_sync(p_driver bigint, p_day date)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  DECLARE
    live dl_entries%rowtype; has_money boolean; valued boolean; anchor bigint; route_txt text;
    prev_flag text;      -- 063: the caller's tms.local_day_sync, given back after the relabel
    stamp text := ' (' || to_char(now() AT TIME ZONE 'Europe/Athens', 'DD/MM/YYYY') || ')';
    sep text := ' ' || chr(183) || ' ';
    -- Greek labels from base64 (this file stays ASCII). Transliterated:
    w_local   text := convert_from(decode('zqTOn86gzpnOms6f', 'base64'), 'UTF8');          -- TOPIKO
    w_deliv   text := convert_from(decode('z4DOsc+BzqzOtM6/z4POtw==', 'base64'), 'UTF8');  -- paradosi
    w_load    text := convert_from(decode('z4bPjM+Bz4TPic+Dzrc=', 'base64'), 'UTF8');      -- fortosi
    t_gone    text := convert_from(decode('zqTOv8+AzrnOus6tz4IgzrrOuc69zq7Pg861zrnPgjogzrrOsc68zq/OsSDOts+Jzr3PhM6xzr3OriDOus6vzr3Ot8+Dzrcgz4TOt8+CIM63zrzOrc+BzrHPgg==', 'base64'), 'UTF8');
                                    -- Topikes kiniseis: kamia zontani kinisi tis imeras
    r_gone    text := convert_from(decode('z4TOv8+AzrnOus6tz4IgzrrOuc69zq7Pg861zrnPgjogzrrOsc68zq/OsSDOts+Jzr3PhM6xzr3OriDPgM65zrE=', 'base64'), 'UTF8');
                                    -- topikes kiniseis: kamia zontani pia
    r_changed text := convert_from(decode('zqzOu867zrHOvs6xzr0gzr/OuSDPhM6/z4DOuc66zq3PgiDOus65zr3Ors+DzrXOuc+CIM+EzrfPgiDOt868zq3Pgc6xz4I=', 'base64'), 'UTF8');
                                    -- allaxan oi topikes kiniseis tis imeras
  BEGIN
    IF p_driver IS NULL OR p_day IS NULL THEN RETURN; END IF;
    -- Serialise every writer of this (driver, day). Without it two relays saved at once (api.js
    -- runs requests in parallel; two dispatchers; an order day move meeting a save) both see "no
    -- line", both INSERT, and the second dies on dl_local_day_live - taking the save with it.
    -- The day enters the key as a number: date-to-text follows DateStyle, and the SQL editor and
    -- PostgREST must take the SAME lock.
    PERFORM pg_advisory_xact_lock(hashtext('dl_local_day'), hashtext(p_driver::text || ':' || (p_day - DATE '2000-01-01')::text));

    -- OWNER-Q2 answered 5/10 (every relay driver: daily TOPIKO line): no driver is exempt and
    -- nothing about the driver is read - a live relay of his that day is the only thing that
    -- decides whether the day has a line.

    -- Label = order numbers only (Order No = orders.id, never renamed), so the label never goes
    -- stale and a changed label always means a changed set of relays.
    SELECT min(lm.id),
           w_local || sep || string_agg(CASE lm.move_kind WHEN 'relay_delivery' THEN w_deliv ELSE w_load END
                                        || ' ' || lm.parent_order_id, sep ORDER BY lm.id)
      INTO anchor, route_txt
      FROM local_moves lm
     WHERE lm.driver_id = p_driver AND lm.move_date = p_day AND lm.move_kind <> 'local'
       AND lm.deleted_at IS NULL AND lm.status <> 'Cancelled';

    SELECT * INTO live FROM dl_entries
     WHERE driver_id = p_driver AND entry_date = p_day AND local_move_id IS NOT NULL AND deleted_at IS NULL;
    -- Money = a non-zero amount. "Value 0" is accounting saying "nothing is owed": a line holding
    -- only zeros is cancelled like an empty one, instead of waiting in review (B-08) for nothing.
    has_money := coalesce(live.trip_value, 0) <> 0 OR coalesce(live.advance, 0) <> 0 OR coalesce(live.expenses, 0) <> 0;
    -- Valued = accounting typed ANY amount, "value 0" included. Used for the relabel below, not for
    -- the cancel path: a day settled at 0 that then gets ANOTHER relay must be looked at again.
    -- With has_money there, the new relay would be settled at 0 silently - no NULL amount (not
    -- pending), a line exists (B-64 quiet). (front review, round 2, 4/10)
    valued := live.trip_value IS NOT NULL OR live.advance IS NOT NULL OR live.expenses IS NOT NULL;

    IF anchor IS NULL THEN                                  -- no live relay left that day
      IF live.id IS NULL THEN RETURN; END IF;
      IF has_money THEN                                     -- possibly owed: flag, never drop silently
        -- Skip only while the line is STILL flagged for this reason (a repeat sync adds no second
        -- note). Not "the reason is somewhere in the note": accounting's check clears the flag and
        -- keeps the note, so after clear -> relay re-added -> relay deleted again that test would
        -- leave a paid line with no relay and no flag (review round 3, 5/10).
        UPDATE dl_entries SET needs_review = true, updated_at = now(),
               review_note = concat_ws(sep, review_note, r_gone || stamp)
         WHERE id = live.id
           AND NOT (needs_review AND position(r_gone IN coalesce(review_note, '')) > 0);
      ELSE
        UPDATE dl_entries SET deleted_at = now(), updated_at = now(), deleted_reason = t_gone
         WHERE id = live.id;
      END IF;
      RETURN;
    END IF;

    IF live.id IS NULL THEN
      -- amounts stay NULL on purpose, same rule as RT lines (owner 5/9): accounting enters them
      INSERT INTO dl_entries (driver_id, entry_type, entry_date, date_end, route, local_move_id, source, created_by)
      VALUES (p_driver, 'trip', p_day, p_day, route_txt, anchor, 'auto', 'trigger:local_move');
      RETURN;
    END IF;

    -- 063: dl_local_line_guard lets a local line's relay or route change only while
    -- tms.local_day_sync = 'on'. Set around the ONE write of this function that changes such a
    -- column, given back right after it - no RETURN in between. Not a SET clause on the function
    -- (a custom setting stored on a function needs superuser; the SQL editor's postgres is not) and
    -- not set once at the top (an early RETURN would leave it 'on' for the rest of the transaction).
    prev_flag := current_setting('tms.local_day_sync', true);
    PERFORM set_config('tms.local_day_sync', 'on', true);
    -- The label belongs to the trigger, not to money: always refreshed. A changed set of relays
    -- after a value was written (even 0) goes to review (B-08); accounting clears it with a reason.
    UPDATE dl_entries SET local_move_id = anchor, route = route_txt, updated_at = now(),
           needs_review = needs_review OR (valued AND route IS DISTINCT FROM route_txt),
           review_note = CASE WHEN valued AND route IS DISTINCT FROM route_txt
                              THEN concat_ws(sep, review_note, r_changed || stamp) ELSE review_note END
     WHERE id = live.id AND (local_move_id IS DISTINCT FROM anchor OR route IS DISTINCT FROM route_txt);
    PERFORM set_config('tms.local_day_sync', coalesce(prev_flag, ''), true);
  END $function$
;
CREATE OR REPLACE FUNCTION public.dl_local_line_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
  BEGIN
    -- 063: who, when and what a local line pays is the relays' (dl_local_day_sync). A hand move
    -- would leave money on a day without a relay while the sync writes a second line for the old day.
    IF (NEW.entry_date, NEW.date_end, NEW.driver_id, NEW.route, NEW.rt_id, NEW.entry_type, NEW.local_move_id)
       IS DISTINCT FROM (OLD.entry_date, OLD.date_end, OLD.driver_id, OLD.route, OLD.rt_id, OLD.entry_type, OLD.local_move_id)
       AND current_setting('tms.local_day_sync', true) IS DISTINCT FROM 'on' THEN
      RAISE EXCEPTION 'local_relay: line % belongs to the relays of its driver and day - its day, driver, route, round trip, type and relay are written only by the system; edit the amounts, the note or the review flag', OLD.id
        USING ERRCODE = '23514', HINT = 'local_relay:line_locked';
    END IF;
    IF OLD.deleted_at IS NOT NULL AND NEW.deleted_at IS NULL THEN
      RAISE EXCEPTION 'local_relay: a cancelled local payroll line is not restored - it comes back by itself when a relay of that driver and day returns'
        USING ERRCODE = '23514', HINT = 'local_relay:line_restore';
    END IF;
    IF OLD.deleted_at IS NULL AND NEW.deleted_at IS NOT NULL
       AND EXISTS (SELECT 1 FROM local_moves lm
                    WHERE lm.driver_id = OLD.driver_id AND lm.move_date = OLD.entry_date AND lm.move_kind <> 'local'
                      AND lm.deleted_at IS NULL AND lm.status <> 'Cancelled') THEN
      RAISE EXCEPTION 'local_relay: line % pays a live relay of that driver and day - enter value 0 or change the relay, do not cancel the line', OLD.id
        USING ERRCODE = '23514', HINT = 'local_relay:line_has_relay';
    END IF;
    RETURN NEW;
  END $function$
;
CREATE OR REPLACE FUNCTION public.dl_sync_from_local_move()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  BEGIN
    -- Plain local moves are never paid by a line (Weekly National errands, as today).
    IF NEW.move_kind = 'local' THEN RETURN NULL; END IF;
    IF TG_OP = 'UPDATE' AND (OLD.driver_id, OLD.move_date) IS DISTINCT FROM (NEW.driver_id, NEW.move_date) THEN
      -- fixed lock order (earlier day, then lower driver id first): two crossing moves cannot deadlock
      IF (OLD.move_date, coalesce(OLD.driver_id, 0)) < (NEW.move_date, coalesce(NEW.driver_id, 0)) THEN
        PERFORM dl_local_day_sync(OLD.driver_id, OLD.move_date);
        PERFORM dl_local_day_sync(NEW.driver_id, NEW.move_date);
      ELSE
        PERFORM dl_local_day_sync(NEW.driver_id, NEW.move_date);
        PERFORM dl_local_day_sync(OLD.driver_id, OLD.move_date);
      END IF;
    ELSE
      PERFORM dl_local_day_sync(NEW.driver_id, NEW.move_date);
    END IF;
    RETURN NULL;
  END $function$
;
CREATE OR REPLACE FUNCTION public.dl_sync_from_rt()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  live dl_entries%rowtype;
  has_amounts boolean;
begin
  select * into live from dl_entries where rt_id = new.id and deleted_at is null limit 1;
  has_amounts := live.trip_value is not null or live.advance is not null or live.expenses is not null;

  -- A ledger line must not sit attributed to a driver who no longer drives
  -- this RT (trip_type moved off OWNED, or the driver was unassigned) with
  -- no trace of it (principle 1): flag it for review if amounts were already
  -- entered, otherwise cancel it — mirrors the RT-cancelled handling below.
  if new.trip_type <> 'OWNED' or new.driver_id is null then
    if live.id is null then
      return new;                                   -- nothing to do
    elsif has_amounts then
      update dl_entries set needs_review = true,
        review_note = 'RT ' || new.code || ' έμεινε χωρίς οδηγό μας ' || to_char(now(), 'DD/MM/YYYY') || ', μετά την καταχώρηση ποσών',
        updated_at = now() where id = live.id;
      return new;
    else
      update dl_entries set deleted_at = now(), deleted_reason = 'RT ' || new.code || ' έμεινε χωρίς οδηγό μας',
        updated_at = now() where id = live.id;
      return new;
    end if;
  end if;

  if live.id is null then
    if new.status <> 'cancelled' then
      -- amounts stay NULL on purpose (owner 5/9): the advance is not always 300
      insert into dl_entries (driver_id, entry_type, entry_date, date_end, rt_id, source, created_by)
      values (new.driver_id, 'trip', new.date_start, new.date_end, new.id, 'auto', 'trigger:' || new.created_by);
    end if;
    return new;
  end if;

  if new.status = 'cancelled' then
    if has_amounts then
      update dl_entries set needs_review = true,
        review_note = 'RT ' || new.code || ' ακυρώθηκε ' || to_char(now(), 'DD/MM/YYYY') || ' μετά την καταχώρηση ποσών',
        updated_at = now() where id = live.id;
    else
      update dl_entries set deleted_at = now(), deleted_reason = 'RT ' || new.code || ' ακυρώθηκε',
        updated_at = now() where id = live.id;
    end if;
    return new;
  end if;

  -- driver and dates ALWAYS follow the RT; a driver change after amounts were
  -- written is flagged, never silently rewritten
  update dl_entries set
    driver_id  = new.driver_id,
    entry_date = new.date_start,
    date_end   = new.date_end,
    needs_review = case when live.driver_id <> new.driver_id and has_amounts then true else needs_review end,
    review_note  = case when live.driver_id <> new.driver_id and has_amounts
                        then 'άλλαξε οδηγός ' || live.driver_id || '→' || new.driver_id || ' στις ' || to_char(now(), 'DD/MM/YYYY') || ', μετά την καταχώρηση ποσών'
                        else review_note end,
    updated_at = now()
  where id = live.id
    and (live.driver_id <> new.driver_id or live.entry_date <> new.date_start
         or live.date_end is distinct from new.date_end);
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.local_moves_before()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
  DECLARE o record; d date;
  BEGIN
    IF TG_OP = 'UPDATE' THEN
      NEW.updated_at := now();
      -- Kind and order are what the payroll line and the auditor key on: never re-pointed.
      IF (OLD.move_kind <> 'local' OR NEW.move_kind <> 'local')
         AND (NEW.move_kind, NEW.parent_order_id, NEW.parent_nat_load_id)
             IS DISTINCT FROM (OLD.move_kind, OLD.parent_order_id, OLD.parent_nat_load_id) THEN
        RAISE EXCEPTION 'local_relay: the kind and the order of a relay never change - delete it and add a new one'
          USING ERRCODE = '23514', HINT = 'local_relay:kind_locked';
      END IF;
    END IF;
    -- Plain local moves (Weekly National, move_kind 'local'): today's behaviour exactly - no
    -- derived status, no refusal here (coordinator 4/10). An unknown kind falls through to
    -- local_moves_kind_chk.
    IF NEW.move_kind IS DISTINCT FROM 'relay_delivery' AND NEW.move_kind IS DISTINCT FROM 'relay_loading' THEN
      RETURN NEW;
    END IF;
    -- Un-deleting or un-cancelling would bring back a relay whose order may have moved on
    -- (rule of 023): the dispatcher adds a new one.
    IF TG_OP = 'UPDATE' AND ((OLD.deleted_at IS NOT NULL AND NEW.deleted_at IS NULL)
                             OR (OLD.status = 'Cancelled' AND NEW.status IS DISTINCT FROM 'Cancelled')) THEN
      RAISE EXCEPTION 'local_relay: a deleted or cancelled relay is not revived - add a new one'
        USING ERRCODE = '23514', HINT = 'local_relay:final';
    END IF;
    IF NEW.status IS NULL OR NEW.status IN ('Pending', 'Assigned') THEN
      NEW.status := CASE WHEN NEW.driver_id IS NOT NULL THEN 'Assigned' ELSE 'Pending' END;
    ELSIF NEW.status <> 'Cancelled' THEN
      RAISE EXCEPTION 'local_relay: a relay is Pending, Assigned or Cancelled - done is read from the order'
        USING ERRCODE = '23514', HINT = 'local_relay:status';
    END IF;
    IF NEW.deleted_at IS NOT NULL OR NEW.status = 'Cancelled' THEN
      RETURN NEW;                                   -- gone: nothing more to check, nothing paid
    END IF;
    IF NEW.parent_order_id IS NULL OR NEW.parent_nat_load_id IS NOT NULL THEN
      RAISE EXCEPTION 'local_relay: a relay serves exactly one international order'
        USING ERRCODE = '23514', HINT = 'local_relay:no_order';
    END IF;
    IF NEW.partner_id IS NOT NULL THEN
      RAISE EXCEPTION 'local_relay: a partner cannot be the local driver of a relay (phase 1)'
        USING ERRCODE = '23514', HINT = 'local_relay:partner';
    END IF;
    IF (NEW.move_kind = 'relay_delivery' AND (NEW.from_location_id IS NULL OR NEW.to_location_id IS NOT NULL))
       OR (NEW.move_kind = 'relay_loading' AND (NEW.to_location_id IS NULL OR NEW.from_location_id IS NOT NULL)) THEN
      RAISE EXCEPTION 'local_relay: a local delivery stores only From (the handover point), a local loading only To'
        USING ERRCODE = '23514', HINT = 'local_relay:points';
    END IF;
    IF NEW.driver_id IS NOT NULL AND NEW.trailer_id IS NULL THEN
      RAISE EXCEPTION 'local_relay: with a local driver the trailer is required'
        USING ERRCODE = '23514', HINT = 'local_relay:no_trailer';
    END IF;

    SELECT id, direction, veroia_switch, status, ops_status, deleted_at, driver_id, loading_datetime, delivery_datetime
      INTO o FROM orders WHERE id = NEW.parent_order_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'local_relay: order % does not exist', NEW.parent_order_id
        USING ERRCODE = '23514', HINT = 'local_relay:no_order';
    END IF;
    -- Shape of the ORDER is checked when the relay is written; an order that changes later is
    -- never blocked - B-65 reports the mismatch the next day.
    IF TG_OP = 'INSERT' THEN
      IF o.deleted_at IS NOT NULL OR o.status = 'Cancelled' THEN
        RAISE EXCEPTION 'local_relay: order % is deleted or cancelled', o.id
          USING ERRCODE = '23514', HINT = 'local_relay:order_gone';
      END IF;
      IF o.ops_status = 'Provisional' THEN
        RAISE EXCEPTION 'local_relay: order % is a pre-order - convert it first', o.id
          USING ERRCODE = '23514', HINT = 'local_relay:preorder';
      END IF;
      IF coalesce(o.veroia_switch, false) THEN
        RAISE EXCEPTION 'local_relay: order % goes through Veroia Switch (cross-dock)', o.id
          USING ERRCODE = '23514', HINT = 'local_relay:vs';
      END IF;
      IF o.direction IS DISTINCT FROM (CASE NEW.move_kind WHEN 'relay_delivery' THEN 'Import' ELSE 'Export' END) THEN
        RAISE EXCEPTION 'local_relay: a local delivery only on an import, a local loading only on an export (order %)', o.id
          USING ERRCODE = '23514', HINT = 'local_relay:direction';
      END IF;
      IF EXISTS (SELECT 1 FROM orders l WHERE l.parent_order_id = o.id AND l.deleted_at IS NULL) THEN
        RAISE EXCEPTION 'local_relay: order % is split - put the relay on the leg', o.id
          USING ERRCODE = '23514', HINT = 'local_relay:split_parent';
      END IF;
      -- local_moves_relay_once is the floor; this only gives the refusal its code.
      IF EXISTS (SELECT 1 FROM local_moves x WHERE x.parent_order_id = o.id AND x.move_kind = NEW.move_kind
                    AND x.deleted_at IS NULL AND x.status <> 'Cancelled') THEN
        RAISE EXCEPTION 'local_relay: order % already has a live relay of this kind', o.id
          USING ERRCODE = '23514', HINT = 'local_relay:relay_exists';
      END IF;
    END IF;
    -- The relay exists because ANOTHER driver does this part; checked whenever the driver is set.
    IF NEW.driver_id IS NOT NULL AND NEW.driver_id = o.driver_id
       AND (TG_OP = 'INSERT' OR NEW.driver_id IS DISTINCT FROM OLD.driver_id) THEN
      RAISE EXCEPTION 'local_relay: the local driver is the international driver of order %', o.id
        USING ERRCODE = '23514', HINT = 'local_relay:same_driver';
    END IF;
    -- The relay day IS the order's customer day (orders dates are DATE: no time zone). Derived,
    -- never typed: a typed Date is replaced, so the Daily, the payroll day and the order agree.
    d := CASE NEW.move_kind WHEN 'relay_delivery' THEN o.delivery_datetime ELSE o.loading_datetime END;
    IF d IS NOT NULL THEN
      NEW.move_date := d;
    ELSIF TG_OP = 'INSERT' THEN
      RAISE EXCEPTION 'local_relay: order % has no % date', o.id,
        CASE NEW.move_kind WHEN 'relay_delivery' THEN 'delivery' ELSE 'loading' END
        USING ERRCODE = '23514', HINT = 'local_relay:no_order_date';
    END IF;  -- an UPDATE after the order lost its date keeps the last day (never block); B-65 'day'
    RETURN NEW;
  END $function$
;
CREATE OR REPLACE FUNCTION public.rt_auto_close(p_rt bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r        ct_round_trips%rowtype;
  n_live   int;
  n_open   int;
  live_dl  dl_entries%rowtype;
begin
  if p_rt is null then return; end if;
  select * into r from ct_round_trips where id = p_rt;
  if r.id is null or r.status = 'cancelled' then return; end if;

  -- 034 (4/10): national legs count with the same definition of «open» as order legs.
  select count(*) filter (where x.deleted_at is null),
         count(*) filter (where x.deleted_at is null
                          and x.status is distinct from 'Delivered'
                          and x.status is distinct from 'Cancelled')
    into n_live, n_open
  from (select o.deleted_at, o.status from ct_rt_legs l join orders o on o.id = l.order_id where l.rt_id = p_rt
        union all
        select nl.deleted_at, nl.status from ct_rt_legs l join national_loads nl on nl.id = l.nat_load_id where l.rt_id = p_rt) x;

  if n_live = 0 then return; end if;

  if n_open > 0 and r.status in ('closed', 'complete') then
    update ct_round_trips
       set status = 'planned', closed_at = null, updated_at = now()
     where id = p_rt;
    perform rt_sync_audit('update', 'ct_round_trips', p_rt::text,
      jsonb_build_object('status', r.status, 'closed_at', r.closed_at),
      jsonb_build_object('status', 'planned', 'closed_at', null, 'open_legs', n_open,
                         'reason', 'reopened: ' || n_open || ' leg(s) not delivered/cancelled (046)'));

    select * into live_dl from dl_entries where rt_id = p_rt and deleted_at is null limit 1;
    if live_dl.id is not null
       and (live_dl.trip_value is not null or live_dl.advance is not null or live_dl.expenses is not null) then
      update dl_entries
         set needs_review = true,
             review_note = concat_ws(' · ', review_note,
               'ο γύρος ' || r.code || ' ξανάνοιξε ' || to_char(now(), 'DD/MM/YYYY') ||
               ' μετά την καταχώρηση ποσών — νέο σκέλος, έλεγξε την αξία (046)'),
             updated_at = now()
       where id = live_dl.id;
    end if;
    return;
  end if;

  if n_open = 0 and r.status in ('planned', 'in_progress') then
    if r.trip_type = 'OWNED' and r.truck_id is null then
      if not exists (
        select 1 from audit_log
         where actor = 'trigger:rt_sync' and table_name = 'ct_round_trips' and record_id = p_rt::text
           and after_data->>'blocked' = 'true'
           and created_at > now() - interval '7 days') then
        perform rt_sync_audit('update', 'ct_round_trips', p_rt::text,
          jsonb_build_object('status', r.status),
          jsonb_build_object('status', r.status, 'blocked', true,
                             'reason', 'not auto-closed: OWNED round trip without a truck (owned_needs_truck) — assign a truck (046)'));
      end if;
      return;
    end if;

    update ct_round_trips
       set status = 'closed', closed_at = now(), updated_at = now()
     where id = p_rt;
    perform rt_sync_audit('update', 'ct_round_trips', p_rt::text,
      jsonb_build_object('status', r.status, 'closed_at', r.closed_at),
      jsonb_build_object('status', 'closed', 'closed_at', now(), 'legs', n_live,
                         'reason', 'auto-closed: all legs delivered/cancelled (046)'));
  end if;
end $function$
;
CREATE OR REPLACE FUNCTION public.rt_auto_close_legs()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if tg_op = 'DELETE' then
    perform rt_auto_close(old.rt_id);
    return null;
  end if;
  perform rt_auto_close(new.rt_id);
  if tg_op = 'UPDATE' and old.rt_id is distinct from new.rt_id then
    perform rt_auto_close(old.rt_id);
  end if;
  return null;
end $function$
;
CREATE OR REPLACE FUNCTION public.rt_recompute(p_rt bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r ct_round_trips%rowtype; n int; d1 date; d2 date;
begin
  select * into r from ct_round_trips where id = p_rt;
  if r.id is null or r.status = 'cancelled' then return; end if;

  select count(*),
         min(coalesce(o.loading_datetime, nl.loading_datetime)::date),
         max(coalesce(o.actual_delivery_date, nl.actual_delivery_date,
                      o.delivery_datetime::date, nl.delivery_datetime::date))
    into n, d1, d2
  from ct_rt_legs l
  left join orders o          on o.id  = l.order_id
  left join national_loads nl on nl.id = l.nat_load_id
  where l.rt_id = p_rt;

  if n = 0 then
    update ct_round_trips
       set status = 'cancelled',
           notes = concat_ws(' · ', notes, 'ακυρώθηκε αυτόματα ' || to_char(now(), 'DD/MM/YYYY') || ': καμία ζωντανή παραγγελία'),
           updated_at = now()
     where id = p_rt;
    perform rt_sync_audit('update', 'ct_round_trips', p_rt::text,
      jsonb_build_object('status', r.status), jsonb_build_object('status', 'cancelled', 'reason', 'no live legs'));
    return;
  end if;

  if d1 is not null and (r.date_start <> d1 or r.date_end is distinct from greatest(d2, d1)) then
    update ct_round_trips set date_start = d1, date_end = greatest(d2, d1), updated_at = now() where id = p_rt;
    perform rt_sync_audit('update', 'ct_round_trips', p_rt::text,
      jsonb_build_object('date_start', r.date_start, 'date_end', r.date_end),
      jsonb_build_object('date_start', d1, 'date_end', greatest(d2, d1)));
  end if;
end $function$
;
CREATE OR REPLACE FUNCTION public.rt_status_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n_open int;
begin
  if new.status is not distinct from old.status then return new; end if;
  if new.status not in ('closed', 'complete') then return new; end if;

  -- 034 (4/10): an open national leg blocks a manual close exactly like an open order leg.
  select count(*) into n_open
  from (select o.deleted_at, o.status from ct_rt_legs l join orders o on o.id = l.order_id where l.rt_id = new.id
        union all
        select nl.deleted_at, nl.status from ct_rt_legs l join national_loads nl on nl.id = l.nat_load_id where l.rt_id = new.id) x
  where x.deleted_at is null
    and x.status is distinct from 'Delivered' and x.status is distinct from 'Cancelled';

  if n_open > 0 then
    raise exception 'Ο γύρος % δεν κλείνει: έχει % σκέλος/σκέλη που δεν είναι Delivered/Cancelled. Κλείνει μόνος του μόλις παραδοθούν όλα (046).',
      new.code, n_open using errcode = 'P0001';
  end if;
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.rt_sync_audit(p_action text, p_table text, p_id text, p_before jsonb, p_after jsonb)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  insert into audit_log (actor, role, action, table_name, record_id, before_data, after_data, created_at)
  values ('trigger:rt_sync', 'system', p_action, p_table, p_id, p_before, p_after, now());
$function$
;
CREATE OR REPLACE FUNCTION public.rt_sync_legs()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare rt ct_round_trips%rowtype; o orders%rowtype;
begin
  if tg_op = 'DELETE' then
    perform rt_recompute(old.rt_id);
    return null;
  end if;
  if new.order_id is not null then
    select * into rt from ct_round_trips where id = new.rt_id;
    select * into o  from orders where id = new.order_id;
    if rt.truck_id is null and rt.driver_id is null and (o.truck_id is not null or o.driver_id is not null) then
      update ct_round_trips
         set driver_id = o.driver_id, truck_id = o.truck_id, trailer_id = o.trailer_id,
             partner_id = o.partner_id,
             trip_type = case when coalesce(o.is_partner_trip, false) then 'PARTNER' else 'OWNED' end,
             updated_at = now()
       where id = rt.id;
    elsif (rt.truck_id is not null or rt.driver_id is not null)
      and (o.driver_id is distinct from rt.driver_id or o.truck_id is distinct from rt.truck_id
        or o.trailer_id is distinct from rt.trailer_id or o.partner_id is distinct from rt.partner_id) then
      update orders
         set driver_id = rt.driver_id, truck_id = rt.truck_id, trailer_id = rt.trailer_id,
             partner_id = rt.partner_id, is_partner_trip = (rt.trip_type = 'PARTNER')
       where id = o.id;
      perform rt_sync_audit('update', 'orders', o.id::text,
        jsonb_build_object('driver_id', o.driver_id, 'truck_id', o.truck_id, 'trailer_id', o.trailer_id, 'partner_id', o.partner_id),
        jsonb_build_object('driver_id', rt.driver_id, 'truck_id', rt.truck_id, 'trailer_id', rt.trailer_id,
                           'partner_id', rt.partner_id, 'source_rt', rt.id, 'reason', 'leg attached'));
    end if;
  end if;
  perform rt_recompute(new.rt_id);
  return null;
end $function$
;
CREATE OR REPLACE FUNCTION public.rt_sync_to_national_loads()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare sib record; is_partner boolean;
begin
  if new.status = 'cancelled' then return null; end if;
  -- An RT that LOST its vehicle (an order cleared on a shared RT, RT-1193 30/9) must not spread the
  -- loss to national loads: only a real re-assignment travels, and NULL is never written.
  if not ((new.trip_type = 'OWNED' and new.truck_id is not null)
       or (new.trip_type = 'PARTNER' and new.partner_id is not null)) then
    return null;
  end if;
  is_partner := new.trip_type = 'PARTNER';
  for sib in
    select nl.id, nl.driver_id, nl.truck_id, nl.trailer_id, nl.partner_id, nl.is_partner_trip
    from ct_rt_legs l join national_loads nl on nl.id = l.nat_load_id
    where l.rt_id = new.id and nl.deleted_at is null
      and (coalesce(nl.is_partner_trip, false) <> is_partner
        or (is_partner and nl.partner_id is distinct from new.partner_id)
        or (not is_partner and (nl.truck_id is distinct from new.truck_id
                                or nl.driver_id is distinct from coalesce(new.driver_id, nl.driver_id)
                                or nl.trailer_id is distinct from coalesce(new.trailer_id, nl.trailer_id))))
  loop
    if is_partner then
      update national_loads set is_partner_trip = true, partner_id = new.partner_id where id = sib.id;
    else
      update national_loads
         set is_partner_trip = false, truck_id = new.truck_id,
             driver_id = coalesce(new.driver_id, driver_id), trailer_id = coalesce(new.trailer_id, trailer_id)
       where id = sib.id;
    end if;
    perform rt_sync_audit('update', 'national_loads', sib.id::text, to_jsonb(sib) - 'id',
      jsonb_build_object('truck_id', new.truck_id, 'driver_id', new.driver_id, 'trailer_id', new.trailer_id,
                         'partner_id', new.partner_id, 'is_partner_trip', is_partner, 'source_rt', new.id,
                         'reason', 'round trip re-assigned — its national leg follows (034)'));
  end loop;
  return null;
end $function$
;
CREATE OR REPLACE FUNCTION public.rt_sync_to_orders()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare sib record; is_partner boolean;
begin
  if new.status = 'cancelled' then return null; end if;
  is_partner := new.trip_type = 'PARTNER';
  for sib in
    select o.id, o.driver_id, o.truck_id, o.trailer_id, o.partner_id, o.is_partner_trip
    from ct_rt_legs l join orders o on o.id = l.order_id
    where l.rt_id = new.id and o.deleted_at is null
      and (o.driver_id  is distinct from new.driver_id  or o.truck_id   is distinct from new.truck_id
        or o.trailer_id is distinct from new.trailer_id or o.partner_id is distinct from new.partner_id
        or coalesce(o.is_partner_trip, false) <> is_partner)
  loop
    update orders
       set driver_id = new.driver_id, truck_id = new.truck_id, trailer_id = new.trailer_id,
           partner_id = new.partner_id, is_partner_trip = is_partner
     where id = sib.id;
    perform rt_sync_audit('update', 'orders', sib.id::text,
      to_jsonb(sib) - 'id',
      jsonb_build_object('driver_id', new.driver_id, 'truck_id', new.truck_id, 'trailer_id', new.trailer_id,
                         'partner_id', new.partner_id, 'is_partner_trip', is_partner, 'source_rt', new.id));
  end loop;
  return null;
end $function$
;
CREATE TRIGGER dl_sync_from_rt AFTER INSERT OR UPDATE ON public.ct_round_trips FOR EACH ROW EXECUTE FUNCTION dl_sync_from_rt();
CREATE TRIGGER rt_status_guard BEFORE UPDATE OF status ON public.ct_round_trips FOR EACH ROW EXECUTE FUNCTION rt_status_guard();
CREATE TRIGGER rt_sync_to_national_loads AFTER UPDATE OF driver_id, truck_id, trailer_id, partner_id, trip_type ON public.ct_round_trips FOR EACH ROW WHEN (((old.driver_id IS DISTINCT FROM new.driver_id) OR (old.truck_id IS DISTINCT FROM new.truck_id) OR (old.trailer_id IS DISTINCT FROM new.trailer_id) OR (old.partner_id IS DISTINCT FROM new.partner_id) OR (old.trip_type IS DISTINCT FROM new.trip_type))) EXECUTE FUNCTION rt_sync_to_national_loads();
CREATE TRIGGER rt_sync_to_orders AFTER UPDATE OF driver_id, truck_id, trailer_id, partner_id, trip_type ON public.ct_round_trips FOR EACH ROW WHEN (((old.driver_id IS DISTINCT FROM new.driver_id) OR (old.truck_id IS DISTINCT FROM new.truck_id) OR (old.trailer_id IS DISTINCT FROM new.trailer_id) OR (old.partner_id IS DISTINCT FROM new.partner_id) OR (old.trip_type IS DISTINCT FROM new.trip_type))) EXECUTE FUNCTION rt_sync_to_orders();
CREATE TRIGGER rt_sync_legs AFTER INSERT OR DELETE ON public.ct_rt_legs FOR EACH ROW EXECUTE FUNCTION rt_sync_legs();
CREATE TRIGGER rt_z_auto_close_legs AFTER INSERT OR DELETE OR UPDATE OF rt_id, order_id ON public.ct_rt_legs FOR EACH ROW EXECUTE FUNCTION rt_auto_close_legs();
CREATE TRIGGER dl_cash_lock BEFORE UPDATE OF expenses ON public.dl_entries FOR EACH ROW EXECUTE FUNCTION dl_cash_lock();
CREATE TRIGGER dl_cash_sync_entry AFTER INSERT OR UPDATE OF rt_id, deleted_at ON public.dl_entries FOR EACH ROW EXECUTE FUNCTION dl_cash_sync_entry();
CREATE TRIGGER dl_local_line_guard BEFORE UPDATE OF deleted_at, entry_date, date_end, driver_id, route, rt_id, entry_type, local_move_id ON public.dl_entries FOR EACH ROW WHEN ((((old.local_move_id IS NOT NULL) OR (new.local_move_id IS NOT NULL)) AND ((old.deleted_at IS DISTINCT FROM new.deleted_at) OR (((((((old.entry_date IS DISTINCT FROM new.entry_date) OR (old.date_end IS DISTINCT FROM new.date_end)) OR (old.driver_id IS DISTINCT FROM new.driver_id)) OR (old.route IS DISTINCT FROM new.route)) OR (old.rt_id IS DISTINCT FROM new.rt_id)) OR (old.entry_type IS DISTINCT FROM new.entry_type)) OR (old.local_move_id IS DISTINCT FROM new.local_move_id))))) EXECUTE FUNCTION dl_local_line_guard();
CREATE TRIGGER dl_sync_from_local_move AFTER INSERT OR UPDATE OF driver_id, move_date, deleted_at, status ON public.local_moves FOR EACH ROW EXECUTE FUNCTION dl_sync_from_local_move();
CREATE TRIGGER local_moves_before BEFORE INSERT OR UPDATE ON public.local_moves FOR EACH ROW EXECUTE FUNCTION local_moves_before();
